import struct
def parse_tlv_sizes(buf: bytes, n: int) -> list[tuple[int, int]]:
    if n < 0:
        raise ValueError('negative count')
    pos, out = 0, []
    def take(k: int) -> int:
        nonlocal pos
        if pos + k > len(buf):
            raise ValueError('truncated buffer')
        start = pos
        pos += k
        return start
    for _ in range(n):
        tag, length = struct.unpack_from('<HI', buf, take(6))
        if tag not in (1, 2):
            raise ValueError(f'unknown tag {tag}')
        take(length)
        out.append((tag, length))
    return out

import struct
def unpack_q16_pairs(raw: bytes) -> list[tuple[int, int]]:
    if len(raw) % 4 != 0:
        raise ValueError('byte length must be a multiple of 4')
    return [struct.unpack_from('<hh', raw, i) for i in range(0, len(raw), 4)]
